export type LogoKey = keyof typeof LOGOS;

const MATCHERS: [RegExp, LogoKey][] = [
  [/ubuntu/i, "ubuntu"],
  [/debian/i, "debian"],
  [/alma/i, "almalinux"],
  [/rocky/i, "rockylinux"],
  [/windows/i, "windows"],
  [/proxmox/i, "proxmox"],
  [/centos/i, "centos"],
  [/fedora/i, "fedora"],
  [/cpanel/i, "cpanel"],
  [/plesk/i, "plesk"],
  [/docker/i, "docker"],
  [/nginx/i, "nginx"],
  [/node\.?js/i, "nodedotjs"],
  [/wordpress/i, "wordpress"],
  [/postgres/i, "postgresql"],
  [/grafana/i, "grafana"],
  [/prometheus/i, "prometheus"],
  [/tailscale/i, "tailscale"],
  [/microk8s|kubernetes|\bk8s\b/i, "kubernetes"],
  [/redis/i, "redis"],
  [/wireguard/i, "wireguard"],
  [/minecraft/i, "minecraft"],
  [/clickhouse/i, "clickhouse"],
  [/\belk\b|elastic/i, "elasticstack"],
  [/superset/i, "apachesuperset"],
  [/opnsense/i, "opnsense"],
  [/haproxy/i, "haproxy"],
  [/webmin/i, "webmin"],
  [/coolify/i, "coolify"],
  [/pterodactyl/i, "pterodactyl"],
  [/mysql/i, "mysql"],
  [/mariadb/i, "mariadb"],
  [/traefik/i, "traefikproxy"],
];

function logoFor(name: string): LogoKey | null {
  return MATCHERS.find(([pattern]) => pattern.test(name))?.[1] ?? null;
}

function monogram(name: string) {
  const words = name.replace(/[^a-z0-9 ]/gi, " ").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "?";
  return (words.length > 1 ? words[0][0] + words[1][0] : words[0].slice(0, 2)).toUpperCase();
}

/** A brand mark on a white tile, so dark logos stay visible in dark mode. Falls back to initials. */
export function BrandLogo({ name, size = "md", className }: { name: string; size?: "sm" | "md" | "lg"; className?: string }) {
  const key = logoFor(name);
  const logo = key ? LOGOS[key] : null;
  const box = size === "sm" ? "size-8 rounded-lg p-1.5" : size === "lg" ? "size-12 rounded-2xl p-2.5" : "size-10 rounded-xl p-2";
  return (
    <span
      aria-hidden
      className={cn("flex shrink-0 items-center justify-center bg-white ring-1 ring-black/10", box, className)}
    >
      {logo ? (
        <svg viewBox="0 0 24 24" className="size-full" fill={logo.hex}>
          <path d={logo.path} />
        </svg>
      ) : (
        <span className={cn("font-semibold text-slate-600", size === "sm" ? "text-[11px]" : "text-[13px]")}>{monogram(name)}</span>
      )}
    </span>
  );
}
